<?phpnamespace App\Livewire\Admin\Users;use App\Models\User;use App\Notifications\User\Everyone\AccountActivated;use Artesaos\SEOTools\Traits\SEOTools as SEOToolsTrait;use Jantinnerezo\LivewireAlert\LivewireAlert;use Livewire\Attributes\Layout;use Livewire\Component;use Livewire\WithPagination;use WireUi\Traits\Actions;class UsersComponent extends Component{    use WithPagination, SEOToolsTrait, LivewireAlert, Actions;    public $search = null;    /**     * Render component     *     * @return Illuminate\View\View     */    #[Layout('components.layouts.admin-app')]    public function render()    {        // Seo        $this->seo()->setTitle( setSeoTitle(__('messages.t_users'), true) );        $this->seo()->setDescription( settings('seo')->description );        return view('livewire.admin.users.users', [            'users' => $this->users        ]);    }    /**     * Get list of users     *     * @return object     */    public function getUsersProperty()    {        return User::latest()            ->whereHas('level')            ->when($this->search, fn($query) => $query->where('email', $this->search))            ->with(['level', 'avatar', 'level.badge'])            ->paginate(10);    }    /**     * Ban selected user     *     * @param integer $id     * @return void     */    public function ban($id)    {        // Update user        User::where('id', $id)->where('status', '!=', 'banned')->update([            'status' => 'banned'        ]);        // Success        $this->notification([            'title'       => __('messages.t_success'),            'description' => __('messages.t_user_has_been_banned_success'),            'icon'        => 'success'        ]);    }    /**     * Delete user     *     * @param integer $id     * @return void     */    public function delete($id)    {        // Delete user        User::where('id', $id)->delete();    }    /**     * Activate account     *     * @param integer $id     * @return void     */    public function activate($id)    {        // Get user        $user = User::where('id', $id)->where('status', 'pending')->firstOrFail();        // Send notification to user        $user->notify( (new AccountActivated)->locale(config('app.locale')) );        // Activate account        $user->status = "active";        $user->save();        // Success        $this->notification([            'title'       => __('messages.t_success'),            'description' => __('messages.t_user_has_been_activated_success'),            'icon'        => 'success'        ]);    }    }